// ============================================================
// Validar entrada — TFO Chequear disponibilidad v3
// ------------------------------------------------------------
// Reglas (CDMX, America/Mexico_City):
//  - Formato ISO 8601 (con o sin offset; si no trae, asume CDMX)
//  - Fecha futura (> ahora CDMX)
//  - Día Lunes a Viernes (weekday 1..5)
//  - Hora ∈ {10, 11, 12} y minutos == 0
// Si falla algo, retorna {valid:false, libre:false, motivo, mensaje} listo para el agente.
// Si pasa, retorna fechas ISO calculadas en CDMX para los nodos siguientes.
// ============================================================

const TZ = 'America/Mexico_City';
const inp = $input.first().json;

const fechaHora = inp.fecha_hora || '';
const nombre = inp.nombre || '';
const subscriberId = inp.subscriber_id || '';
const canal = inp.canal || '';
const telefono = inp.telefono || '';

const makeFail = (motivo, mensaje) => [{
  json: {
    valid: false,
    libre: false,
    motivo,
    mensaje,
    alternativas: [],
    fecha_hora_solicitada: fechaHora,
    nombre, subscriber_id: subscriberId, canal, telefono
  }
}];

// 1) Parseo ISO en zona CDMX
let dt;
try {
  dt = DateTime.fromISO(fechaHora, { zone: TZ });
  if (!dt.isValid) throw new Error(dt.invalidReason || 'invalid');
} catch (e) {
  return makeFail(
    'formato_invalido',
    'No pude entender la fecha y hora que me pasaron. Pedile al lead que la repita con día y hora claros (ej: "lunes 9 de junio a las 11:00").'
  );
}

const now = DateTime.now().setZone(TZ);

// 2) Futura
if (dt <= now) {
  return makeFail(
    'fecha_pasada',
    'Esa fecha ya pasó. Proponé un horario futuro: lunes a viernes, 10:00, 11:00 o 12:00 (hora México).'
  );
}

// 3) Lunes a Viernes
if (dt.weekday > 5) {
  return makeFail(
    'no_laboral',
    'Solo tomamos reuniones de lunes a viernes. Proponé un día hábil a las 10:00, 11:00 o 12:00 (hora México).'
  );
}

// 4) Hora en ventana laboral
if (![10, 11, 12].includes(dt.hour)) {
  return makeFail(
    'fuera_ventana',
    'Las reuniones son a las 10:00, 11:00 o 12:00 hs (hora México). Proponé un horario dentro de ese rango.'
  );
}

// 5) Minutos redondos
if (dt.minute !== 0 || dt.second !== 0) {
  return makeFail(
    'minutos_no_redondos',
    'Las reuniones empiezan en hora exacta. Proponé 10:00, 11:00 o 12:00 (hora México).'
  );
}

// VÁLIDO — devuelve los campos calculados
return [{
  json: {
    valid: true,
    fecha_inicio: dt.toISO(),
    fecha_fin: dt.plus({ minutes: 30 }).toISO(),
    fecha_dia_inicio: dt.startOf('day').toISO(),
    fecha_dia_fin: dt.endOf('day').toISO(),
    fecha_humana: dt.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm"),
    fecha_hora_solicitada: fechaHora,
    nombre, subscriber_id: subscriberId, canal, telefono
  }
}];

// ============================================================
// Evaluar solapamiento + calcular alternativas
// ------------------------------------------------------------
// Slots ocupados vienen como ítems con {start, end} (ISO).
// Si Google Calendar no devolvió slots, $input.all() es array vacío
// o con un ítem sin start/end (alwaysOutputData=true en el calendar).
// ============================================================

const TZ = 'America/Mexico_City';
const val = $('Validar entrada').first().json;

const fechaInicio = DateTime.fromISO(val.fecha_inicio, { zone: TZ });
const fechaFin = DateTime.fromISO(val.fecha_fin, { zone: TZ });

// Slots ocupados desde el nodo Calendar
const slots = $input.all()
  .map(s => s.json)
  .filter(s => s && s.start && s.end)
  .map(s => ({
    start: DateTime.fromISO(s.start, { zone: TZ }),
    end: DateTime.fromISO(s.end, { zone: TZ })
  }));

// Solapamiento de intervalos [s1,e1) vs [s2,e2)
const solapa = (s1, e1, s2, e2) => s1 < e2 && s2 < e1;

// ¿Está ocupado el horario solicitado?
const ocupada = slots.some(o => solapa(fechaInicio, fechaFin, o.start, o.end));

if (!ocupada) {
  return [{ json: { ...val, libre: true } }];
}

// Calcular alternativas: cupos {10,11,12} del MISMO día (excluyendo el solicitado)
const dia = fechaInicio.startOf('day');
const cupos = [10, 11, 12];
const alternativas = [];

for (const h of cupos) {
  const iniCupo = dia.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
  const finCupo = iniCupo.plus({ minutes: 30 });
  // Saltar el cupo solicitado (ya sabemos que está ocupado)
  if (+iniCupo === +fechaInicio) continue;
  const libreCupo = !slots.some(o => solapa(iniCupo, finCupo, o.start, o.end));
  if (libreCupo) alternativas.push(iniCupo.toFormat('HH:mm'));
}

const mensaje = alternativas.length > 0
  ? `Ese horario está ocupado. Para ese mismo día tengo libre: ${alternativas.join(', ')} (hora México).`
  : 'Ese horario está ocupado y no me quedan otros cupos disponibles ese día. Proponé otro día (lunes a viernes, 10:00, 11:00 o 12:00 hora México).';

return [{
  json: {
    ...val,
    libre: false,
    motivo: 'ocupado',
    mensaje,
    alternativas
  }
}];

